package com.spuitelf;

import lombok.Getter;
import net.runelite.api.GameObject;

import java.util.HashMap;
import java.util.Map;

public enum CalcifiedRockConfig {
    CALCIFIED_ROCK(70, new int[]{
            51485,
            51487,
            51491,
    });

    @Getter
    private final int maxTicks;
    private final int[] rockIds;
    private static final Map<Integer, CalcifiedRockConfig> rockMap = new HashMap<>();

    static {
        for (CalcifiedRockConfig rockConfig : values()) {
            for (int rockId : rockConfig.rockIds) {
                rockMap.put(rockId, rockConfig);
            }
        }
    }

    CalcifiedRockConfig(int maxSeconds, int[] rockIds) {
        this.maxTicks = (int) Math.round(maxSeconds / 0.6d);
        this.rockIds = rockIds;
    }

    static CalcifiedRockConfig getRockById(int gameObjectId) {
        return rockMap.get(gameObjectId);
    }

    static boolean isCalcifiedRock(GameObject gameObject) {
        return rockMap.containsKey(gameObject.getId());
    }
}

package com.spuitelf;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup(CalcifiedRockDespawnTimerConfig.GROUP_NAME)
public interface CalcifiedRockDespawnTimerConfig extends Config {
    String GROUP_NAME = "calcifiedrock-despawn-timer";

    @ConfigItem(
            keyName = "timerType",
            name = "Timer Display Type",
            position = 1,
            description = "The UI style for displaying the estimated remaining time on each calcified rock."
    )
    default TimerTypes timerType() {
        return TimerTypes.PIE;
    }

    @ConfigItem(
            keyName = "resetTimerDisplayType",
            name = "Reset Timer",
            position = 2,
            description = "Display how long an unmined active rock has before its timer resets to full duration."
    )
    default ResetTimerDisplayTypes resetTimerDisplayType() {
        return ResetTimerDisplayTypes.OFF;
    }

    @ConfigSection(
            name = "Advanced UI Customization",
            description = "Detailed options for customizing timer overlay",
            position = 3,
            closedByDefault = true
    )
    String uiCustomizationSection = "uiCustomizationSection";

    @ConfigItem(
            keyName = "timerColorLow",
            name = "Timer Color Low",
            position = 0,
            description = "Overlay color when the rock is about to despawn.",
            section = uiCustomizationSection
    )
    default Color timerColorLow() {
        return new Color(220, 0, 0);
    }

    @ConfigItem(
            keyName = "timerColorMedium",
            name = "Timer Color Medium",
            position = 1,
            description = "Overlay color when the rock is nearly running out of time.",
            section = uiCustomizationSection
    )
    default Color timerColorMedium() {
        return new Color(230, 160, 0);
    }

    @ConfigItem(
            keyName = "timerColorHigh",
            name = "Timer Color High",
            position = 2,
            description = "Overlay color when the rock is fairly new.",
            section = uiCustomizationSection
    )
    default Color timerColorHigh() {
        return new Color(230, 230, 0);
    }

    @ConfigItem(
            keyName = "timerColorFull",
            name = "Timer Color Full",
            position = 3,
            description = "Overlay color when the rock timer is newly started.",
            section = uiCustomizationSection
    )
    default Color timerColorFull() {
        return new Color(0, 255, 0);
    }

    @ConfigItem(
            keyName = "resetTimerColor",
            name = "Reset Timer Color",
            position = 4,
            description = "Overlay color for the reset timer text.",
            section = uiCustomizationSection
    )
    default Color resetTimerColor() {
        return Color.WHITE;
    }

    String UI_SIZE_NORMAL = "uiSizeNormal";

    @ConfigItem(
            keyName = UI_SIZE_NORMAL,
            name = "UI Size Normal",
            position = 5,
            description = "Size of the timer.",
            section = uiCustomizationSection
    )
    default int uiSizeNormal() {
        return 16;
    }

    @ConfigSection(
            name = "Debug",
            description = "Basic debugging features.",
            position = 4,
            closedByDefault = true
    )
    String debugSection = "debugSection";

    @ConfigItem(
            keyName = "debugLevel",
            name = "Debug Level",
            description = "Controls the amount of debug information displayed.",
            section = debugSection
    )
    default DebugLevel debugLevel() {
        return DebugLevel.NONE;
    }

}

package com.spuitelf;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

import javax.inject.Inject;
import java.awt.*;
import java.time.Duration;

public class CalcifiedRockDespawnTimerOverlay extends Overlay {
    private static final int TIMER_Y_OFFSET = -10;
    private static final int RESET_TEXT_SPACING = 2;

    private final CalcifiedRockDespawnTimerPlugin plugin;
    private final CalcifiedRockDespawnTimerConfig config;
    private final Client client;

    @Inject
    private CalcifiedRockDespawnTimerOverlay(CalcifiedRockDespawnTimerPlugin plugin, CalcifiedRockDespawnTimerConfig config, Client client) {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        for (CalcifiedRockState rockState : plugin.uniqueRocks) {
            if (!rockState.shouldShowTimer()) {
                continue;
            }
            LocalPoint lp = LocalPoint.fromWorld(client, rockState.worldPoint);
            if (lp == null) {
                continue;
            }
            LocalPoint centeredPoint = new LocalPoint(lp.getX() + rockState.centerOffset.getX(),
                    lp.getY() + rockState.centerOffset.getY(), client.getTopLevelWorldView());
            Point point = Perspective.localToCanvas(client,
                    centeredPoint,
                    client.getTopLevelWorldView().getPlane());
            if (point == null) {
                continue;
            }
            Point renderPoint = new Point(point.getX(), point.getY() + TIMER_Y_OFFSET);
            if (config.timerType() == TimerTypes.PIE) {
                ProgressPieComponent pie = new ProgressPieComponent();
                pie.setPosition(renderPoint);
                pie.setBorderColor(rockState.getTimerColor());
                pie.setDiameter(config.uiSizeNormal());
                pie.setFill(rockState.getTimerColor());
                pie.setProgress(rockState.getTimePercent());
                pie.render(graphics);
            } else if (config.timerType() == TimerTypes.TICKS) {
                String text = rockState.getTimeTicks().toString();
                CustomTextComponent textComponent = new CustomTextComponent(text,
                        new java.awt.Point(renderPoint.getX(), renderPoint.getY()));
                textComponent.setColor(rockState.getTimerColor());
                textComponent.render(graphics);
            } else if (config.timerType() == TimerTypes.SECONDS) {
                Duration duration = Duration.ofSeconds(rockState.getTimeSeconds(plugin.getSubTick()));
                String text = String.format("%s%d:%02d",
                        duration.toSeconds() < 0 ? "-" : "",
                        Math.abs(duration.toMinutesPart()),
                        Math.abs(duration.toSecondsPart()));
                CustomTextComponent textComponent = new CustomTextComponent(text,
                        new java.awt.Point(renderPoint.getX(), renderPoint.getY()));
                textComponent.setColor(rockState.getTimerColor());
                textComponent.render(graphics);
            }

            if (shouldRenderResetText(rockState)) {
                String resetText = formatResetText(rockState);
                CustomTextComponent resetTextComponent = new CustomTextComponent(
                        resetText,
                        new java.awt.Point(renderPoint.getX(), renderPoint.getY() + config.uiSizeNormal() + RESET_TEXT_SPACING)
                );
                resetTextComponent.setColor(config.resetTimerColor());
                resetTextComponent.render(graphics);
            }
        }
        return null;
    }

    private boolean shouldRenderResetText(CalcifiedRockState rockState) {
        return config.resetTimerDisplayType() != ResetTimerDisplayTypes.OFF && rockState.shouldShowResetTimer();
    }

    private String formatResetText(CalcifiedRockState rockState) {
        if (config.resetTimerDisplayType() == ResetTimerDisplayTypes.TICKS) {
            return String.valueOf(rockState.getResetTicksRemaining());
        }

        Duration duration = Duration.ofSeconds(rockState.getResetSecondsRemaining());
        return String.format("%d:%02d", Math.abs(duration.toMinutesPart()), Math.abs(duration.toSecondsPart()));
    }
}

package com.spuitelf;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.coords.Angle;
import net.runelite.api.coords.Direction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.annotation.Nullable;
import javax.inject.Inject;
import java.util.*;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@PluginDescriptor(
        name = "Calcified Rock Despawn Timer",
        description = "Show an estimate of the remaining time until a calcified rock despawns",
        configName = CalcifiedRockDespawnTimerConfig.GROUP_NAME
)
public class CalcifiedRockDespawnTimerPlugin extends Plugin {
    private static final int CAM_TORUM_REGION = 6037;
    private static final int CAM_TORUM_STREAM_OBJECT_ID = 51493;
    private static final int STREAM_TIMER_SECONDS = 30;
    private static final Set<Integer> MINING_WALL_ANIMATIONS = ImmutableSet.of(
            AnimationID.HUMAN_MINING_3A_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_ADAMANT_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_BLACK_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_BRONZE_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_CRYSTAL_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_DRAGON_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_ZALCANO_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_TRAILBLAZER_PICKAXE_NO_INFERNAL_WALL,
            AnimationID.HUMAN_MINING_DRAGON_PICKAXE_PRETTY_WALL,
            AnimationID.HUMAN_MINING_GILDED_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_INFERNAL_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_TRAILBLAZER_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_TRAILBLAZER_RELOADED_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_IRON_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_MITHRIL_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_RUNE_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_STEEL_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_LEAGUE_TRAILBLAZER_PICKAXE_WALL,
            AnimationID.HUMAN_MINING_TRAILBLAZER_RELOADED_PICKAXE_NO_INFERNAL_WALL
    );

    @Inject
    private Client client;

    @Inject
    private CalcifiedRockDespawnTimerConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private CalcifiedRockDespawnTimerOverlay calcifiedRockDespawnTimerOverlay;

    @Getter
    private int subTick = 0;

    private final ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);
    private ScheduledFuture<?> subTickFuture;
    private final HashMap<WorldPoint, CalcifiedRockState> rockAtLocation = new HashMap<>();
    protected HashSet<CalcifiedRockState> uniqueRocks = new HashSet<>();
    private final HashSet<WorldPoint> streamLocations = new HashSet<>();
    private final HashMap<Player, CalcifiedRockState> playerMiningRock = new HashMap<>();
    private final ArrayList<Runnable> deferTickQueue = new ArrayList<>();
    private final HashSet<Player> startupSuppressedMiningPlayers = new HashSet<>();
    private boolean sceneStateSynchronized = false;
    private boolean synchronizingScene = false;
    private int lastLocalMiningXp = -1;
    private int nextGarbageCollect = 25;
    private int nextAnimationRecheck = 0;

    @Provides
    CalcifiedRockDespawnTimerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(CalcifiedRockDespawnTimerConfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        CustomTextComponent.updateFontSizes(config.uiSizeNormal(), config.uiSizeNormal());
        overlayManager.add(calcifiedRockDespawnTimerOverlay);
        deferTickQueue.add(() -> client.getTopLevelWorldView().players().forEach(this::handlePlayerMining));
        subTickFuture = executor.scheduleAtFixedRate(
                () -> subTick += Constants.CLIENT_TICK_LENGTH,
                0,
                Constants.CLIENT_TICK_LENGTH,
                TimeUnit.MILLISECONDS
        );
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(calcifiedRockDespawnTimerOverlay);
        clearTrackedState();
        subTickFuture.cancel(false);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(CalcifiedRockDespawnTimerConfig.GROUP_NAME)) {
            return;
        }
        if (event.getKey().equals(CalcifiedRockDespawnTimerConfig.UI_SIZE_NORMAL)) {
            CustomTextComponent.updateFontSizes(config.uiSizeNormal(), config.uiSizeNormal());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGGING_IN) {
            clearTrackedState();
        }
    }

    @Subscribe
    public void onGameTick(GameTick gameTick) {
        if (!inCamTorumMiningArea()) {
            clearTrackedState();
            subTick = 0;
            return;
        }

        if (!sceneStateSynchronized) {
            synchronizeSceneState();
            sceneStateSynchronized = true;
        }

        deferTickQueue.forEach(Runnable::run);
        deferTickQueue.clear();

        HashSet<CalcifiedRockState> minedRocks = new HashSet<>(playerMiningRock.values());
        uniqueRocks.forEach(rock -> rock.tick(minedRocks.contains(rock)));
        nextGarbageCollect--;
        if (nextGarbageCollect <= 0) {
            ArrayList<CalcifiedRockState> toDelete = new ArrayList<>();
            nextGarbageCollect = 25; // 15 seconds
            Player localPlayer = client.getLocalPlayer();
            uniqueRocks.forEach(rock -> {
                boolean isFarAway = localPlayer != null
                        && rock.worldPoint.getPlane() == localPlayer.getWorldLocation().getPlane()
                        && rock.worldPoint.distanceTo(localPlayer.getWorldLocation()) > 150;
                if (isFarAway && !rock.shouldShowTimer(DebugLevel.NONE)) {
                    toDelete.add(rock);
                }
            });
            toDelete.forEach(this::deleteRock);
        }
        // Mining animations can initially face the wrong direction, so recheck periodically.
        nextAnimationRecheck--;
        if (nextAnimationRecheck <= 0) {
            nextAnimationRecheck = 4;
            client.getTopLevelWorldView().players().forEach(this::handlePlayerMining);
        }
        subTick = 0;
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        GameObject gameObject = event.getGameObject();
        if (!CalcifiedRockConfig.isCalcifiedRock(gameObject)) {
            return;
        }
        trackRock(gameObject);
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        GameObject gameObject = event.getGameObject();
        if (!CalcifiedRockConfig.isCalcifiedRock(gameObject)) {
            return;
        }
        CalcifiedRockState rockState = rockAtLocation.get(gameObject.getWorldLocation());
        if (rockState == null) {
            return;
        }
        if (DebugLevel.BASIC.shouldShow(config.debugLevel())) {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE,
                    "CRDT DEBUG",
                    rockState.rockName.toLowerCase() + " despawned with " + rockState.getTimeSeconds(getSubTick()) + "s remaining",
                    "");
        }
        deleteRock(rockState);
    }

    @Subscribe
    public void onDecorativeObjectSpawned(DecorativeObjectSpawned event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        DecorativeObject decorativeObject = event.getDecorativeObject();
        if (decorativeObject.getId() != CAM_TORUM_STREAM_OBJECT_ID) {
            return;
        }

        WorldPoint streamPoint = decorativeObject.getWorldLocation();
        streamLocations.add(streamPoint);

        CalcifiedRockState streamRock = rockAtLocation.get(streamPoint);
        if (streamRock != null) {
            streamRock.forceStreamTimerSeconds(STREAM_TIMER_SECONDS);
        }
    }

    @Subscribe
    public void onDecorativeObjectDespawned(DecorativeObjectDespawned event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        DecorativeObject decorativeObject = event.getDecorativeObject();
        if (decorativeObject.getId() != CAM_TORUM_STREAM_OBJECT_ID) {
            return;
        }

        WorldPoint streamPoint = decorativeObject.getWorldLocation();
        streamLocations.remove(streamPoint);

        CalcifiedRockState streamRock = rockAtLocation.get(streamPoint);
        if (streamRock != null && !isRockUnderStream(streamRock)) {
            streamRock.clearStreamTimer();
        }
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        if (event.getActor() instanceof Player) {
            Player player = (Player) event.getActor();
            deferTickQueue.add(() -> this.handlePlayerMining(player));
        }
    }

    @Subscribe
    public void onPlayerDespawned(PlayerDespawned event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        playerMiningRock.remove(event.getPlayer());
        startupSuppressedMiningPlayers.remove(event.getPlayer());
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (!inCamTorumMiningArea()) {
            return;
        }

        if (event.getSkill() != Skill.MINING) {
            return;
        }

        int currentXp = event.getXp();
        if (lastLocalMiningXp < 0) {
            lastLocalMiningXp = currentXp;
            return;
        }
        if (currentXp <= lastLocalMiningXp) {
            return;
        }
        lastLocalMiningXp = currentXp;

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return;
        }

        if (startupSuppressedMiningPlayers.contains(localPlayer)) {
            return;
        }

        CalcifiedRockState interactingRock = playerMiningRock.get(localPlayer);
        if (interactingRock == null) {
            interactingRock = findClosestFacingRock(localPlayer);
            if (interactingRock != null) {
                playerMiningRock.put(localPlayer, interactingRock);
            }
        }

        if (interactingRock != null) {
            interactingRock.startTimer();
        }
    }

    void handlePlayerMining(Player player) {
        if (!isMiningCalcifiedRock(player)) {
            playerMiningRock.remove(player);
            startupSuppressedMiningPlayers.remove(player);
            return;
        }

        if (startupSuppressedMiningPlayers.contains(player)) {
            playerMiningRock.remove(player);
            return;
        }

        CalcifiedRockState interactingRock = findClosestFacingRock(player);
        if (interactingRock == null) {
            playerMiningRock.remove(player);
            return;
        }

        if (player == client.getLocalPlayer()) {
            playerMiningRock.put(player, interactingRock);
            return;
        }

        interactingRock.startTimer();
        playerMiningRock.put(player, interactingRock);
    }

    void deleteRock(CalcifiedRockState rockState) {
        playerMiningRock.entrySet().removeIf(entry -> entry.getValue() == rockState);
        rockState.points.forEach(rockAtLocation::remove);
        uniqueRocks.remove(rockState);
    }

    private void clearTrackedState() {
        rockAtLocation.clear();
        uniqueRocks.clear();
        streamLocations.clear();
        playerMiningRock.clear();
        startupSuppressedMiningPlayers.clear();
        deferTickQueue.clear();
        sceneStateSynchronized = false;
        lastLocalMiningXp = -1;
    }

    private void synchronizeSceneState() {
        Scene scene = client.getTopLevelWorldView().getScene();
        Tile[][][] tiles = scene.getTiles();
        HashSet<WorldPoint> scannedRockLocations = new HashSet<>();

        synchronizingScene = true;
        try {
            for (Tile[][] planeTiles : tiles) {
                for (Tile[] columnTiles : planeTiles) {
                    for (Tile tile : columnTiles) {
                        if (tile == null) {
                            continue;
                        }

                        DecorativeObject decorativeObject = tile.getDecorativeObject();
                        if (decorativeObject != null && decorativeObject.getId() == CAM_TORUM_STREAM_OBJECT_ID) {
                            // Existing streams at login/hop have unknown age, so only track presence.
                            streamLocations.add(decorativeObject.getWorldLocation());
                        }

                        GameObject[] gameObjects = tile.getGameObjects();
                        for (GameObject gameObject : gameObjects) {
                            if (gameObject == null || !CalcifiedRockConfig.isCalcifiedRock(gameObject)) {
                                continue;
                            }

                            if (scannedRockLocations.add(gameObject.getWorldLocation())) {
                                trackRock(gameObject);
                            }
                        }
                    }
                }
            }
        } finally {
            synchronizingScene = false;
        }

        // Existing streams at login/hop have unknown age; still suppress reset tracking while present.
        uniqueRocks.forEach(rock -> rock.setStreamTimerActive(isRockUnderStream(rock)));

        client.getTopLevelWorldView().players().forEach(player -> {
            if (isMiningCalcifiedRock(player)) {
                startupSuppressedMiningPlayers.add(player);
            }
        });
    }

    private void trackRock(GameObject gameObject) {
        CalcifiedRockState existing = rockAtLocation.get(gameObject.getWorldLocation());
        if (existing != null) {
            deleteRock(existing);
        }

        CalcifiedRockState rockState = new CalcifiedRockState(gameObject, client, config);
        rockState.points.forEach(point -> rockAtLocation.put(point, rockState));
        uniqueRocks.add(rockState);
        if (!synchronizingScene) {
            applyStreamTimerIfPresent(rockState);
        }
    }

    private void applyStreamTimerIfPresent(CalcifiedRockState rockState) {
        if (isRockUnderStream(rockState)) {
            rockState.forceStreamTimerSeconds(STREAM_TIMER_SECONDS);
        }
    }

    private boolean isRockUnderStream(CalcifiedRockState rockState) {
        return rockState.points.stream().anyMatch(streamLocations::contains);
    }

    private boolean inCamTorumMiningArea() {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return false;
        }

        WorldPoint worldPoint = localPlayer.getWorldLocation();
        return worldPoint != null && worldPoint.getRegionID() == CAM_TORUM_REGION;
    }

    @Nullable
    CalcifiedRockState findClosestFacingRock(Player player) {
        WorldPoint actorLocation = player.getWorldLocation();
        Direction direction = new Angle(player.getOrientation()).getNearestDirection();
        WorldPoint facingPoint = neighborPoint(actorLocation, direction);
        return rockAtLocation.get(facingPoint);
    }

    private WorldPoint neighborPoint(WorldPoint point, Direction direction) {
        switch (direction) {
            case NORTH:
                return point.dy(1);
            case SOUTH:
                return point.dy(-1);
            case EAST:
                return point.dx(1);
            case WEST:
                return point.dx(-1);
            default:
                throw new IllegalStateException();
        }
    }

    private boolean isMiningCalcifiedRock(Player player) {
        return MINING_WALL_ANIMATIONS.contains(player.getAnimation());
    }
}

package com.spuitelf;

import net.runelite.api.Point;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;

import java.awt.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;

public class CalcifiedRockState {
    static final int RESET_AFTER_UNMINED_TICKS = 56;
    static final int RESET_DISPLAY_AFTER_UNMINED_TICKS = 5;

    WorldPoint worldPoint;
    Point centerOffset;
    List<WorldPoint> points;
    String rockName;
    boolean timerStarted = false;

    private int ticksLeft;
    private final int maxTicks;
    private int unminedTicks = 0;
    private boolean minedThisTick = false;
    private boolean streamTimerActive = false;
    private final Client client;
    private final CalcifiedRockDespawnTimerConfig config;

    public CalcifiedRockState(GameObject rock, Client client, CalcifiedRockDespawnTimerConfig config) {
        worldPoint = rock.getWorldLocation();
        this.client = client;
        this.config = config;
        CalcifiedRockConfig rockConfig = CalcifiedRockConfig.getRockById(rock.getId());
        rockName = rockConfig.name();
        maxTicks = rockConfig.getMaxTicks();
        ticksLeft = maxTicks;
        centerOffset = getCenterOffset(rock);
        points = getPoints(rock);
    }

    void startTimer() {
        if (ticksLeft <= 0) {
            ticksLeft = maxTicks;
        }
        if (!timerStarted) {
            timerStarted = true;
        }
        unminedTicks = 0;
    }

    void forceTimerSeconds(int seconds) {
        int forcedTicks = (int) Math.ceil((seconds * 1000d) / Constants.GAME_TICK_LENGTH);
        ticksLeft = Math.max(forcedTicks, 0);
        timerStarted = true;
        streamTimerActive = false;
        unminedTicks = 0;
    }

    void forceStreamTimerSeconds(int seconds) {
        int forcedTicks = (int) Math.ceil((seconds * 1000d) / Constants.GAME_TICK_LENGTH);
        ticksLeft = Math.max(forcedTicks, 0);
        timerStarted = true;
        streamTimerActive = true;
        unminedTicks = 0;
    }

    void clearStreamTimer() {
        streamTimerActive = false;
    }

    void setStreamTimerActive(boolean streamTimerActive) {
        this.streamTimerActive = streamTimerActive;
        if (streamTimerActive) {
            unminedTicks = 0;
        }
    }

    void tick(boolean minedThisTick) {
        this.minedThisTick = minedThisTick;
        if (!timerStarted) {
            unminedTicks = 0;
            return;
        }

        if (streamTimerActive) {
            unminedTicks = 0;
            if (ticksLeft > 0) {
                ticksLeft--;
            }
            return;
        }

        if (minedThisTick) {
            unminedTicks = 0;
            if (ticksLeft > 0) {
                ticksLeft--;
            }
            return;
        }

        unminedTicks++;
        if (unminedTicks >= RESET_AFTER_UNMINED_TICKS) {
            ticksLeft = maxTicks;
            timerStarted = false;
            unminedTicks = 0;
            return;
        }

        if (ticksLeft > 0) {
            ticksLeft--;
        }
    }

    boolean shouldShowTimer(DebugLevel debugLevel) {
        if (DebugLevel.BASIC.shouldShow(debugLevel) && !timerStarted) {
            return true;
        }
        return timerStarted;
    }

    boolean shouldShowTimer() {
        return shouldShowTimer(config.debugLevel());
    }

    Color getTimerColor() {
        double percent = getTimePercent() * 100;
        if (percent < 15) {
            return config.timerColorLow();
        }
        if (percent < 40) {
            return config.timerColorMedium();
        }
        if (percent < 80) {
            return config.timerColorHigh();
        }
        return config.timerColorFull();
    }

    Float getTimePercent() {
        return Math.max(ticksLeft / (float) maxTicks, 0f);
    }

    Integer getTimeTicks() {
        return Math.max(ticksLeft, 0);
    }

    Integer getTimeSeconds(int subTickMs) {
        int tickDelta = timerStarted && ticksLeft > 0 ? -1 : 0;
        int secondsLeft = (int) Math.floor((ticksLeft * Constants.GAME_TICK_LENGTH + subTickMs * tickDelta) / 1000f);
        return Math.max(secondsLeft, 0);
    }

    boolean shouldShowResetTimer() {
        return timerStarted
                && !streamTimerActive
                && !minedThisTick
                && unminedTicks >= RESET_DISPLAY_AFTER_UNMINED_TICKS;
    }

    Integer getResetTicksRemaining() {
        return Math.max(RESET_AFTER_UNMINED_TICKS - unminedTicks, 0);
    }

    Integer getResetSecondsRemaining() {
        return (int) Math.ceil((getResetTicksRemaining() * Constants.GAME_TICK_LENGTH) / 1000d);
    }

    private List<WorldPoint> getPoints(GameObject gameObject) {
        WorldPoint minPoint = getSWWorldPoint(gameObject);
        WorldPoint maxPoint = getNEWorldPoint(gameObject);

        if (minPoint.equals(maxPoint)) {
            return Collections.singletonList(minPoint);
        }

        final int plane = minPoint.getPlane();
        final List<WorldPoint> list = new ArrayList<>();
        for (int x = minPoint.getX(); x <= maxPoint.getX(); x++) {
            for (int y = minPoint.getY(); y <= maxPoint.getY(); y++) {
                list.add(new WorldPoint(x, y, plane));
            }
        }
        return list;
    }

    private Point getCenterOffset(GameObject gameObject) {
        int x = 0;
        int y = 0;
        if (gameObject.sizeX() % 2 == 0) {
            x = (gameObject.sizeX() - 1) * Perspective.LOCAL_HALF_TILE_SIZE;
        }
        if (gameObject.sizeY() % 2 == 0) {
            y = (gameObject.sizeY() - 1) * Perspective.LOCAL_HALF_TILE_SIZE;
        }
        return new Point(x, y);
    }

    private WorldPoint getSWWorldPoint(GameObject gameObject) {
        return getWorldPoint(gameObject, GameObject::getSceneMinLocation);
    }

    private WorldPoint getNEWorldPoint(GameObject gameObject) {
        return getWorldPoint(gameObject, GameObject::getSceneMaxLocation);
    }

    private WorldPoint getWorldPoint(GameObject gameObject, Function<GameObject, Point> pointFunction) {
        Point point = pointFunction.apply(gameObject);
        return WorldPoint.fromScene(client.getTopLevelWorldView(),  point.getX(), point.getY(), gameObject.getPlane());
    }

}

package com.spuitelf;

import lombok.Setter;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.RenderableEntity;

import java.awt.*;

public class CustomTextComponent implements RenderableEntity {
    private final String text;
    private final Point position;
    @Setter
    private Color color = Color.BLACK;
    @Setter
    private boolean emphasize = false;
    @Setter
    private boolean centered = true;

    private static Font emphasizeFont = FontManager.getRunescapeBoldFont().deriveFont(16f);
    private static Font standardFont = FontManager.getRunescapeSmallFont().deriveFont(16f);

    static void updateFontSizes(int normal, int emphasized) {
        standardFont = FontManager.getRunescapeSmallFont().deriveFont((float) normal);
        // Bold font is naturally much larger than the small font, so scale down the size to keep them in-line
        emphasizeFont = FontManager.getRunescapeBoldFont().deriveFont((float) Math.round(emphasized * 0.65f));
    }

    public CustomTextComponent(String text, Point position) {
        this.text = text;
        this.position = position;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Font originalFont = graphics.getFont();
        graphics.setFont(emphasize ? emphasizeFont : standardFont);

        final FontMetrics fontMetrics = graphics.getFontMetrics();
        int textWidth = fontMetrics.stringWidth(text);
        int textHeight = fontMetrics.getAscent();

        if (centered) {
            position.setLocation(position.getX() - textWidth / 2d, position.getY() + textHeight / 2d);
        }

        graphics.setColor(Color.BLACK);
        if (emphasize) {
            graphics.drawString(text, position.x, position.y - 1);
            graphics.drawString(text, position.x - 1, position.y);
        }
        graphics.drawString(text, position.x, position.y + 1);
        graphics.drawString(text, position.x + 1, position.y);

        graphics.setColor(color);
        graphics.drawString(text, position.x, position.y);

        if (originalFont != null) {
            graphics.setFont(originalFont);
        }

        return new Dimension(textWidth, textHeight);
    }
}

